L23_1.m_CharScale = L24_1
L23_1.m_CharScaleTime = 0.01
L23_1.m_Talk_KOREA = "\236\159\164\235\138\148 <color=#ffd34c>\237\148\188\235\157\188\235\131\144</color>, \236\160\128\234\184\176 \236\160\128 \237\129\176 \234\177\180 <color=#ffd34c>\237\148\188\235\157\188\235\163\168\236\191\160</color>\236\149\188. \235\170\168\235\145\144 \236\149\132\235\167\136\236\161\180\236\151\144\236\132\156 \235\176\156\234\178\172\237\149\160 \236\136\152 \236\158\136\236\167\128."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "\227\129\130\227\130\140\227\129\175<color=#ffd34c>\227\131\148\227\131\169\227\131\139\227\130\162</color>\227\128\129\227\129\130\227\129\157\227\129\147\227\129\174\229\164\167\227\129\141\227\129\132\227\129\174\227\129\175<color=#ffd34c>\227\131\148\227\131\169\227\131\171\227\130\175\227\131\188</color>\227\129\160\227\130\136\227\128\130\227\129\169\227\129\163\227\129\161\227\130\130\227\130\162\227\131\158\227\130\190\227\131\179\227\129\167\232\166\139\227\130\137\227\130\140\227\130\139\227\129\174\227\128\130"
L23_1.m_Talk_ENG = "That one's a <color=#ffd34c>piranha</color>, and that big one is called a <color=#ffd34c>pirarucu</color>. They can all be found in the Amazon."
L23_1.m_Talk_TWN = "\231\137\160\230\152\175<color=#ffd34c>\233\163\159\228\186\186\233\173\154</color>\239\188\140, \229\190\136\229\164\167\231\154\132\233\130\163\230\162\157\230\152\175<color=#ffd34c>\232\177\161\233\173\154</color>\239\188\140\231\137\160\229\128\145\233\131\189\230\152\175\229\156\168\228\186\158\233\166\172\233\129\156\230\178\179\228\184\173\231\153\188\231\143\190\231\154\132\229\150\148\227\128\130"
L23_1.m_Talk_SCN = "\232\191\153\230\152\175<color=#ffd34c>\233\163\159\228\186\186\233\177\188</color>\239\188\140\233\130\163\232\190\185\233\130\163\228\184\170\229\164\167\229\174\182\228\188\153\230\152\175<color=#ffd34c>\229\183\168\233\170\168\232\136\140\233\177\188</color>\227\128\130\229\174\131\228\187\172\233\131\189\229\135\186\230\178\161\228\186\142\228\186\154\233\169\172\233\128\138\227\128\130"
L23_1.m_Talk_DEU = "Das hier ist ein <color=#ffd34c>Piranha</color>, und der gro\195\159e hei\195\159t <color=#ffd34c>Pirarucu</color>. Sie wurden beide im Amazons entdeckt."
L23_1.m_Talk_FRA = "Celui-ci, c'est un <color=#ffd34c>piranha</color>, et le gros l\195\160, c'est un <color=#ffd34c>pirarucu</color>. Ils sont tous deux originaires d'Amazonie."
